-- BetterPack Initial Schema
-- Simple, working schema for MVP

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Gear items table
CREATE TABLE gear_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  weight_grams INTEGER NOT NULL,
  category TEXT DEFAULT 'Other',
  quantity INTEGER DEFAULT 1,
  worn BOOLEAN DEFAULT FALSE,
  consumable BOOLEAN DEFAULT FALSE,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Trip lists table
CREATE TABLE trip_lists (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  gear_ids TEXT[], -- Just an array of IDs for now, normalize later if needed
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security
ALTER TABLE gear_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE trip_lists ENABLE ROW LEVEL SECURITY;

-- RLS Policies for gear_items
CREATE POLICY "Users can view own gear" ON gear_items
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own gear" ON gear_items
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own gear" ON gear_items
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own gear" ON gear_items
  FOR DELETE USING (auth.uid() = user_id);

-- RLS Policies for trip_lists
CREATE POLICY "Users can view own lists" ON trip_lists
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own lists" ON trip_lists
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own lists" ON trip_lists
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own lists" ON trip_lists
  FOR DELETE USING (auth.uid() = user_id);

-- Indexes for performance
CREATE INDEX idx_gear_items_user_id ON gear_items(user_id);
CREATE INDEX idx_trip_lists_user_id ON trip_lists(user_id);

-- Updated at trigger function
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ language 'plpgsql';

-- Add triggers for updated_at
CREATE TRIGGER update_gear_items_updated_at BEFORE UPDATE ON gear_items
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_trip_lists_updated_at BEFORE UPDATE ON trip_lists
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

import { lazy, Suspense } from 'react'
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom'
import { QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { AuthProvider, useAuth } from './contexts/AuthContext'
import { ProtectedRoute } from './components/auth/ProtectedRoute'
import { Toaster } from './components/ui/toaster'
import { Skeleton } from './components/ui/skeleton'
import { queryClient } from './lib/queryClient'
import './App.css'

// Lazy load heavy pages for code splitting
const LoginForm = lazy(() => import('./components/auth/LoginForm').then(m => ({ default: m.LoginForm })))
const SignupForm = lazy(() => import('./components/auth/SignupForm').then(m => ({ default: m.SignupForm })))
const Dashboard = lazy(() => import('./pages/Dashboard').then(m => ({ default: m.Dashboard })))
const GearCloset = lazy(() => import('./pages/GearCloset').then(m => ({ default: m.GearCloset })))

// Loading fallback component
function PageLoader() {
  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="space-y-4 w-full max-w-md">
        <Skeleton className="h-12 w-3/4 mx-auto" />
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-8 w-1/2 mx-auto" />
      </div>
    </div>
  )
}

function AppRoutes() {
  const { user } = useAuth()

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        <Route 
          path="/" 
          element={user ? <Navigate to="/dashboard" /> : <Navigate to="/login" />} 
        />
        <Route 
          path="/login" 
          element={user ? <Navigate to="/dashboard" /> : <LoginForm />} 
        />
        <Route 
          path="/signup" 
          element={user ? <Navigate to="/dashboard" /> : <SignupForm />} 
        />
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <Dashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/gear"
          element={
            <ProtectedRoute>
              <GearCloset />
            </ProtectedRoute>
          }
        />
      </Routes>
    </Suspense>
  )
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Router>
        <AuthProvider>
          <AppRoutes />
          <Toaster />
        </AuthProvider>
      </Router>
      {process.env.NODE_ENV === 'development' && !window.navigator.webdriver && <ReactQueryDevtools initialIsOpen={false} />}
    </QueryClientProvider>
  )
}

export default App

import { TripList } from '@/types/database'

interface TripListViewProps {
  lists: TripList[]
  onSelect: (list: TripList) => void
}

export function TripListView({ lists, onSelect }: TripListViewProps) {
  return (
    <div className="bg-white rounded-lg shadow">
      <div className="p-4 border-b">
        <h2 className="text-xl font-semibold">Trip Lists</h2>
      </div>
      <div className="divide-y">
        {lists.length === 0 ? (
          <p className="p-4 text-gray-500">No trip lists created yet</p>
        ) : (
          lists.map((list) => (
            <button
              key={list.id}
              onClick={() => onSelect(list)}
              className="w-full p-4 text-left hover:bg-gray-50 transition-colors"
            >
              <h3 className="font-medium">{list.name}</h3>
              <p className="text-sm text-gray-600 mt-1">
                {list.gear_ids.length} items • Created {new Date(list.created_at).toLocaleDateString()}
              </p>
            </button>
          ))
        )}
      </div>
    </div>
  )
}
